using System;using System.IO;using System.Collections.Generic;using System.Numerics;using ScoreModern.RecoveredFragments;
class CoordinateConversionProof {
 class Memory:IHorizontalRasterMemory {public Dictionary<int,byte> Bytes=new Dictionary<int,byte>();public List<string> Events=new List<string>();public void Load(ushort seg,byte[] data){for(int i=0;i<data.Length;i++){int p=(seg<<4)+i;byte old;if(Bytes.TryGetValue(p,out old)&&old!=data[i])throw new Exception("Alias mismatch");Bytes[p]=data[i];}}public ushort ReadWord(ushort s,ushort o){byte a,b;Bytes.TryGetValue((s<<4)+o,out a);Bytes.TryGetValue((s<<4)+(ushort)(o+1),out b);ushort v=(ushort)(a|b<<8);Events.Add("R:"+s+":"+o+":"+v);return v;}public void WriteWord(ushort s,ushort o,ushort v){Events.Add("W:"+s+":"+o+":"+v);Bytes[(s<<4)+o]=(byte)v;Bytes[(s<<4)+(ushort)(o+1)]=(byte)(v>>8);}public void OrByte(ushort s,ushort o,byte m){throw new Exception("Video effect");}public Memory Copy(){Memory m=new Memory();foreach(var p in Bytes)m.Bytes[p.Key]=p.Value;return m;}public void Compare(ushort seg,byte[] data){if(data.Length!=65536)throw new Exception("Capture length");for(int i=0;i<65536;i++)if(Bytes[(seg<<4)+i]!=data[i])throw new Exception("Segment offset "+i.ToString("X4"));}}
 class Fpu:ICoordinateFpuEffects {public ushort CW;public uint Bits;public int Pops,Waits;public List<string> Events=new List<string>();public void Wait(){Waits++;Events.Add("WAIT");}public void StoreControlWord(IHorizontalRasterMemory m,ushort s,ushort o){Events.Add("STORE_CW");m.WriteWord(s,o,CW);}public void LoadControlWord(IHorizontalRasterMemory m,ushort s,ushort o){Events.Add("LOAD_CW");CW=m.ReadWord(s,o);}public void StoreInteger64AndPop(IHorizontalRasterMemory m,ushort s,ushort o){Events.Add("STORE_I64_POP");if((CW&0xc00)!=0xc00)throw new Exception("Unverified rounding mode");long value;if(!FiniteBinary32Integer64.TryConvert(Bits,out value))throw new Exception("Input outside finite projection");for(int i=0;i<4;i++)m.WriteWord(s,(ushort)(o+2*i),(ushort)(unchecked((ulong)value)>>(16*i)));Pops++;}}
 static ushort H(string s){return Convert.ToUInt16(s,16);}static SignedDivide16State Parse(string[] a,int i){return new SignedDivide16State{AX=H(a[i]),BX=H(a[i+1]),CX=H(a[i+2]),DX=H(a[i+3]),SI=H(a[i+4]),DI=H(a[i+5]),BP=H(a[i+6]),CS=H(a[i+7]),IP=H(a[i+8]),DS=H(a[i+9]),ES=H(a[i+10]),SS=H(a[i+11]),SP=H(a[i+12]),EFlags=Convert.ToUInt32(a[i+13],16)};}
 static string Show(SignedDivide16State s){return s.AX+":"+s.BX+":"+s.CX+":"+s.DX+":"+s.SI+":"+s.DI+":"+s.BP+":"+s.CS+":"+s.IP+":"+s.DS+":"+s.ES+":"+s.SS+":"+s.SP+":"+s.EFlags;}
 static SignedDivide16State Interpret(byte[] code,Memory m,Fpu f,SignedDivide16State s){int pc=0;Func<byte> next=()=>code[pc++];Func<ushort> word=()=>{byte b=next();return (ushort)(b|next()<<8);};while(pc<50){switch(next()){
 case 0x55:s.SP=(ushort)(s.SP-2);m.WriteWord(s.SS,s.SP,s.BP);break;
 case 0x53:s.SP=(ushort)(s.SP-2);m.WriteWord(s.SS,s.SP,s.BX);break;case 0x51:s.SP=(ushort)(s.SP-2);m.WriteWord(s.SS,s.SP,s.CX);break;case 0x56:s.SP=(ushort)(s.SP-2);m.WriteWord(s.SS,s.SP,s.SI);break;case 0x57:s.SP=(ushort)(s.SP-2);m.WriteWord(s.SS,s.SP,s.DI);break;
 case 0x8b:byte mov=next();if(mov==0xec)s.BP=s.SP;else if(mov==0xe5)s.SP=s.BP;else if(mov==0x46)s.AX=m.ReadWord(s.SS,(ushort)(s.BP+(sbyte)next()));else if(mov==0x56)s.DX=m.ReadWord(s.SS,(ushort)(s.BP+(sbyte)next()));else throw new Exception("MOV");break;
 case 0x83:if(next()!=0xec)throw new Exception("SUB");s.SP=(ushort)(s.SP-(sbyte)next());break;
 case 0x9b:f.Wait();break;case 0x90:break;
 case 0xd9:byte op=next();ushort at=(ushort)(s.BP+(sbyte)next());if(op==0x7e)f.StoreControlWord(m,s.SS,at);else if(op==0x6e)f.LoadControlWord(m,s.SS,at);else throw new Exception("D9");break;
 case 0xdf:if(next()!=0x7e)throw new Exception("DF");f.StoreInteger64AndPop(m,s.SS,(ushort)(s.BP+(sbyte)next()));break;
 case 0x80:if(next()!=0xcc)throw new Exception("OR AH");byte high=(byte)((s.AX>>8)|next());s.AX=(ushort)((s.AX&255)|(high<<8));s.EFlags=IndependentFlagArithmetic.Result(s.EFlags,0,high,8);break;
 case 0x89:if(next()!=0x46)throw new Exception("Store");m.WriteWord(s.SS,(ushort)(s.BP+(sbyte)next()),s.AX);break;
 case 0x5f:s.DI=m.ReadWord(s.SS,s.SP);s.SP=(ushort)(s.SP+2);break;case 0x5e:s.SI=m.ReadWord(s.SS,s.SP);s.SP=(ushort)(s.SP+2);break;case 0x59:s.CX=m.ReadWord(s.SS,s.SP);s.SP=(ushort)(s.SP+2);break;case 0x5b:s.BX=m.ReadWord(s.SS,s.SP);s.SP=(ushort)(s.SP+2);break;case 0x5d:s.BP=m.ReadWord(s.SS,s.SP);s.SP=(ushort)(s.SP+2);break;
 default:throw new Exception("Instruction");}}
 if(pc!=50||code[pc]!=0xcb)throw new Exception("Return boundary");s.IP=0xca2;return s;}
 static int Main(string[] a){try{
 if(a.Length>0){string prefix=Path.Combine(a[0],"case-"+a[1]);uint bits=Convert.ToUInt32(a[2],16);ushort cw=H(a[3]);SignedDivide16State before=Parse(a,4),after=Parse(a,18);Memory m=new Memory();m.Load(before.DS,File.ReadAllBytes(prefix+"-entry-ds.bin"));m.Load(before.SS,File.ReadAllBytes(prefix+"-entry-ss.bin"));Fpu f=new Fpu{CW=cw,Bits=bits};bool returned=a.Length>32&&a[32]=="return";var actual=returned?CoordinateConversion.ExecuteThroughReturn(m,f,before):CoordinateConversion.Execute(m,f,before);if(Show(actual)!=Show(after))throw new Exception("Runtime "+Show(actual)+" != "+Show(after));m.Compare(before.DS,File.ReadAllBytes(prefix+"-exit-ds.bin"));m.Compare(before.SS,File.ReadAllBytes(prefix+"-exit-ss.bin"));if(f.CW!=cw||f.Pops!=1||f.Waits!=2||string.Join(",",f.Events.ToArray())!="WAIT,STORE_CW,WAIT,LOAD_CW,STORE_I64_POP,LOAD_CW")throw new Exception("FPU request contract");Console.WriteLine("PASS original coordinate helper: 13 register words/full EFLAGS, all DS/SS bytes, control-word requests, eight-byte integer and far-return="+returned+". x87 status/tag/exception behavior remains external.");return 0;}
 byte[] code=ConvertHex("558bec83ec0c535156579bd97efe909b8b46fe80cc0c8946fc90d96efc90df7ef490d96efe8b46f48b56f65f5e595b8be55dcb");int count=0;uint[] inputs={0x3fe00000,0xbfe00000,0x4f000000,0xcf000001};for(int sp=0;sp<65536;sp++)for(int k=0;k<4;k++){SignedDivide16State state=new SignedDivide16State{AX=(ushort)(sp^0x1234),BX=(ushort)(sp*3),CX=(ushort)(sp*7),DX=(ushort)(sp*11),SI=(ushort)(sp*13),DI=(ushort)(sp*17),BP=(ushort)(sp*19),SS=0x2000,DS=0x2000,CS=0x20dd,IP=0xc70,SP=(ushort)sp,EFlags=unchecked((uint)(sp*65537+0x72ff))};Memory first=new Memory(),second=first.Copy();Fpu x=new Fpu{CW=(ushort)(sp^0x1370),Bits=inputs[k]},y=new Fpu{CW=x.CW,Bits=x.Bits};var p=CoordinateConversion.Execute(first,x,state);var q=Interpret(code,second,y,state);if(Show(p)!=Show(q)||first.Events.Count!=second.Events.Count||first.Bytes.Count!=second.Bytes.Count||x.CW!=y.CW||string.Join(",",x.Events.ToArray())!=string.Join(",",y.Events.ToArray()))throw new Exception("Instruction model");for(int i=0;i<first.Events.Count;i++)if(first.Events[i]!=second.Events[i])throw new Exception("Ordered word effect");foreach(var v in first.Bytes)if(second.Bytes[v.Key]!=v.Value)throw new Exception("Memory");count++;}
 Random random=new Random(0xc70);int numeric=0;for(int i=0;i<1048576;i++){uint bits=unchecked((uint)random.Next()<<1)|(uint)random.Next(2);float v=BitConverter.ToSingle(BitConverter.GetBytes(bits),0);bool expected=false;BigInteger integer=0;if(!float.IsNaN(v)&&!float.IsInfinity(v)){integer=new BigInteger((double)v);expected=integer>=long.MinValue&&integer<=long.MaxValue;}long result;bool actual=FiniteBinary32Integer64.TryConvert(bits,out result);if(actual!=expected||(actual&&new BigInteger(result)!=integer))throw new Exception("Numeric projection");numeric++;}
 Console.WriteLine("PASS "+count+" original-instruction helper comparisons with external FPU effects: all SP words, four finite inputs, word wrap, control words, ordered effects and full CPU flags.");Console.WriteLine("PASS "+numeric+" independent BigInteger binary32 numeric comparisons, including explicit unsupported-input classification. No original x87 invalid-result/status policy inferred.");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static byte[] ConvertHex(string s){byte[] b=new byte[s.Length/2];for(int i=0;i<b.Length;i++)b[i]=Convert.ToByte(s.Substring(i*2,2),16);return b;}
